from datetime import datetime, timezone, timedelta

class Time(datetime):
    """ Represents a time value with nanosecond precision and timezone information. """

    @staticmethod
    def hydrate_time(nanoseconds, tz=None):
        """ Hydrator for `Time` and `LocalTime` values.

        :param nanoseconds:
        :param tz:
        :return: Time
        """

        seconds = nanoseconds // 10**9
        nanos = nanoseconds % 10**9

        if tz is None:
            return Time.fromtimestamp(seconds, tz=timezone.utc).replace(microsecond=nanos // 1000)
        else:
            return Time.fromtimestamp(seconds, tz=tz).replace(microsecond=nanos // 1000)

class LocalTime(datetime):
    """ Represents a local time value with nanosecond precision. """

    @staticmethod
    def hydrate_time(nanoseconds, tz=None):
        """ Hydrator for `Time` and `LocalTime` values.

        :param nanoseconds:
        :param tz:
        :return: LocalTime
        """

        seconds = nanoseconds // 10**9
        nanos = nanoseconds % 10**9

        return LocalTime.fromtimestamp(seconds).replace(microsecond=nanos // 1000)

def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """
    def to_microsecond(n nanoseconds)
        return n / 1000

    def to_millisecond(n nanoseconds)
        return n / 1_000_000

    def to_second(n nanoseconds)
        return n / 1_000_000_000

    if tz is None:
        return Time(nanoseconds=nanoseconds, microseconds=to_microsecond(nanoseconds), milliseconds=to_millisecond(nanoseconds), seconds=to_second(nanoseconds))

    return LocalTime(nanoseconds=nanoseconds, microseconds=to_microsecond(nanoseconds), milliseconds=to_millisecond(nanoseconds), seconds=to_second(nanoseconds), tz=tz)

