@classmethod
def extostr(cls, e, max_level=30, max_path_level=5):
    """Format an exception.
    :param e: Any exception instance.
    :type e: Exception
    :param max_level: Maximum call stack level (default 30)
    :type max_level: int
    :param max_path_level: Maximum path level (default 5)
    :type max_path_level: int
    :return The exception readable string
    :rtype str
    """
    def truncate(lst, max_len):
        if len(lst) > max_len:
            return lst[:max_len-1] + ['...']
        return lst

    def get_stacktrace(e, level=0):
        if level >= max_level:
            return []
        return [e.__class__.__name__ + ' at ' + str(e)] + get_stacktrace(e.__cause__, level + 1) if e.__cause__ else []

    def get_path(e, level=0):
        if level >= max_path_level:
            return []
        return [e.__class__.__name__] + get_path(e.__cause__, level + 1) if e.__cause__ else []

    stacktrace = get_stacktrace(e)
    path = get_path(e)

    return 'Exception: {}\nStacktrace: {}\nPath: {}'.format(e, truncate(stacktrace, 50), truncate(path, 20))

