def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""

    # Sort classes by inheritance depth
    classes.sort(key=lambda x: x.__mro__.index(object))

    # Remove classes that are subclasses of other classes in the list
    result = []
    for cls in classes:
        if not any(issubclass(cls, c) for c in result):
            result.append(cls)

    return result

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""

    base_order = {
        'object': 0,
        'Element': 1,
        'AbstractElement': 2,
        'SentenceElement': 3,
        'TextElement': 4,
        'TextContent': 5,
        'AbstractStructureElement': 6,
        'StructureElement': 7
    }

    minimal = []
    for cls in classes:
        if all(base_order[base_class] < base_order[cls.__name__] for base_class in minimal):
            minimal = [cls]
        elif base_order[cls.__name__] == base_order[minimal[-1].__name__]:
            minimal.append(cls)

    return minimal

