    if fixity is None:
        raise ValueError("Fixity block is required")

    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")

    allowed_files = set(manifest_files)

    for file_id, file_info in fixity.items():
        if file_id not in allowed_files:
            raise ValueError(f"File {file_id} not found in manifest")

        if not isinstance(file_info, dict):
            raise ValueError(f"File info for {file_id} must be a dictionary")

        required_keys = {'hash', 'size'}
        if not required_keys.issubset(file_info):
            raise ValueError(f"Required keys for file info of {file_id} not present")

        if not isinstance(file_info['hash'], str):
