def pretty(self, indent=0, debug=False):
    """Return a pretty formatted representation of self."""
    indent_str = ' ' * indent
    if debug:
        return indent_str + "DEBUG: " + str(self)
    return str(self)

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """

    output = " " * indent + self.__class__.__name__ + "(\n"
    indent += 4

    for key, value in self.__dict__.items():
        if isinstance(value, list):
            output += " " * indent + key + "=[\n"
            for item in value:
                if isinstance(item, AbstractElement):
                    output += item.pretty(indent + 4) + ",\n"
                else:
                    output += " " * (indent + 8) + repr(item) + ",\n"
            output += " " * indent + "],\n"
        elif isinstance(value, AbstractElement):
            output += " " * indent + key + "=" + value.pretty(indent + 4) + ",\n"
        else:
            output += " " * indent + key + "=" + repr(value) + ",\n"

    indent -= 4
    output += " " * indent + ")\n"

    if debug:
        output += " " * indent + "Debug info:\n"
        indent += 4
        for key, value in self.__dict__.items():
            output += " " * indent + key + "=" + repr(value) + "\n"
        indent -= 4

    return output

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    lines = []
    prefix = "    " * indent
    if debug:
        lines.append(f"{prefix}<{self.__class__.__name__} id={self.id}>")
    else:
        lines.append(f"{prefix}<{self.__class__.__name__}>")
    for key, value in self.__dict__.items():
        if isinstance(value, str):
            lines.append(f"{prefix}  {key}: {value!r}")
        elif isinstance(value, list):
            if value:
                lines.append(f"{prefix}  {key}: [")
                for item in value:
                    if isinstance(item, AbstractElement):
                        lines.extend(item.pretty(indent + 2, debug).split('\n'))
                    else:
                        lines.append(f"{prefix}    {item!r}")
                lines.append(f"{prefix}  ]")
            else:
                lines.append(f"{prefix}  {key}: []")
        elif isinstance(value, AbstractElement):
            lines.extend(value.pretty(indent + 2, debug).split('\n'))
    lines.append(f"{prefix}</{self.__class__.__name__}>")
    return '\n'.join(lines)

