def absorb(args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """

    def apply_absorption(expr):
        if isinstance(expr, (And, Or)):
            if isinstance(expr.left, expr.__class__):
                return expr.left
            elif isinstance(expr.right, expr.__class__):
                return expr.right
        elif isinstance(expr, Not):
            if isinstance(expr.left, expr.__class__):
                return expr.left
        return expr

    def apply_negative_absorption(expr):
        if isinstance(expr, And):
            if isinstance(expr.right, Not) and expr.left == expr.right.left:
                return expr.right.left
        elif isinstance(expr, Or):
            if isinstance(expr.left, Not) and expr.left.left == expr.right:
                return expr.right
        return expr

    result = []
    for arg in args:
        while True:
            absorbed = apply_absorption(arg)
            if absorbed is arg:
                break
            arg = absorbed

        while True:
            inverted_absorbed = apply_negative_absorption(arg)
            if inverted_absorbed is arg:
                break
            arg = inverted_absorbed

        result.append(arg)

    return result

