def parse_subparser_arguments(unparsed_arguments, subparsers):
    parsed_namespaces = {}
    remaining_arguments = []

    for subparser_name, parser in subparsers.items():
        namespace, leftover_args = parser.parse_known_args(unparsed_arguments)
        if namespace:
            parsed_namespaces[subparser_name] = namespace
        else:
            remaining_arguments.extend(leftover_args)

    return parsed_namespaces, remaining_arguments

def parse_subparser_arguments(unparsed_arguments, subparsers):
    parsed_namespaces = {}
    remaining_arguments = unparsed_arguments

    for subparser_name, subparser in subparsers.items():
        parser = argparse.ArgumentParser(parents=[subparser])
        namespace, remaining_args = parser.parse_known_args(remaining_arguments)
        parsed_namespaces[subparser_name] = namespace
        remaining_arguments = remaining_args

