import subprocess

def addignored(ignored):
    ''' Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma.'''

    # Use git command to get the list of ignored files
    git_command = ['git', 'status', '--ignored', '--short']
    result = subprocess.run(git_command, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)

    if result.returncode != 0:
        raise Exception(f"Git command failed: {result.stderr}")

    # Split the output into lines and filter out the ignored files
    ignored_files = []
    for line in result.stdout.strip().split('\n'):
        if not line:
            continue
        status, filename = line.split(' ', 1)
        if status.startswith('!!'):
            ignored_files.append(filename)

    # Sort the list of ignored files
    ignored_files.sort()

    # Join the filenames into a single string separated by commas
    return ','.join(ignored_files)

def addignored(ignored):
    ''' Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma.'''
    result = subprocess.run(['git', 'ls-files', '--ignored'], capture_output=True, text=True)
    files = result.stdout.splitlines()
    ignored_files = [file for file in files if file in ignored]
    return ','.join(sorted(ignored_files))

