import logging
def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.'''

    config_results = {}
    parse_errors = []

    for config_filename in config_filenames:
        try:
            with open(config_filename, 'r') as config_file:
                config_data = config_file.read()
                if resolve_env:
                    config_data = config_data.replace('${HOME}', os.path.expanduser('~'))
                    config_data = config_data.replace('${USER}', os.getlogin())

                config = json.loads(config_data)
                config_results[config_filename] = config

                if overrides:
                    config.update(overrides)

        except FileNotFoundError:
            parse_errors.append(logging.LogRecord(level=logging.ERROR, msg=f"Configuration file not found: {config_filename}", exc_info=True))
        except json.JSONDecodeError as e:
            parse_errors.append(logging.LogRecord(level=logging.ERROR, msg=f"Error parsing configuration file {config_filename}: {e}", exc_info=True))
        except Exception as e:
            parse_errors.append(logging.LogRecord(level=logging.ERROR, msg=f"Unexpected error processing configuration file {config_filename}: {e}", exc_info=True))

    return config_results, parse_errors

