def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type

    Arguments:
        settings_dirs (list of str): List of directories to search for files
        spec_option (dict): Specification options for file names

    Returns:
        list of str: List of file names matching the specifications
    """
    file_names = []
    for directory in settings_dirs:
        for root, _, files in os.walk(directory):
            for file in files:
                if file_match(file, spec_option):
                    file_names.append(os.path.join(root, file))
    return file_names

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    if not isinstance(settings_dirs, list):
        raise ValueError("settings_dirs must be a list")

    file_names = []
    for settings_dir in settings_dirs:
        if isinstance(settings_dir, str):
            # Assuming a function get_files_in_directory exists to retrieve files
            directory_contents = get_files_in_directory(settings_dir)
            if spec_option == 'all':
                file_names.extend(directory_contents)
            elif spec_option == 'py_files':
                file_names.extend([file for file in directory_contents if file.endswith('.py')])
            else:
